import{z as o,x as A,o as r,c as d,q as t,j as n,D as s,d as e,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"分支与变更管理","description":"","frontmatter":{"title":"分支与变更管理","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/swe-branching-changes.md","filePath":"cs/swe-branching-changes.md","lastUpdated":1791063341000}'),p={name:"cs/swe-branching-changes.md"};function h(c,a,m,f,u,C){const B=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="分支与变更管理" tabindex="-1">分支与变更管理 <a class="header-anchor" href="#分支与变更管理" aria-label="Permalink to &quot;分支与变更管理&quot;">​</a></h1><div class="epigraph"><p>分支廉价，相遇昂贵；分支策略的全部内容，是控制两条改动线再次相遇时要付的那笔账。</p><footer>—— 据 Chacon and Straub, Pro Git 的分支与合并章节整理</footer></div><p><a href="/cs/swe-git-internals">上一课</a>把 git 拆成内容寻址的对象库，分支只是一个可移动的指针，创建近乎免费。正因免费，「何时开、开多久、何时合、合不进去怎么办」才成为纯工程问题。本课写：单一主干与短命分支的拓扑，合并与变基在对象图上的后果，变更进主干前的评审与门禁，以及坏改动的退路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单一主干上并行改动会互相踩；用长期并行分支隔离，又积累漂移：分叉越久，两个分支相对共同祖先走得越远，合并时冲突面越大，最后合并一次痛一周。变更管理的缺口因此是一套规则：谁、在什么条件下、能把改动放进主干；以及放错了怎么在分钟内退出来，而不是靠一次新的冒险把它冲掉。</p><p><span class="marginnote">代个数感受漂移速度：主干每天进 100 个提交，你的分支拖两周才合，共同祖先之后多了约 1400 个提交可能与你的改动落进同一批文件；拖两天则只有约 200 个。「分叉时长是唯一要压缩的量」说的就是这个分母。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拓扑取最简：主干（main）保持随时可发布；每个变更一支短命分支，天级生命周期，小步合并回来。合入用三方合并：机器找两支的共同祖先作 base，把两边相对 base 的改动叠加；只有两边改了 base 同一处才报冲突。变基把本支提交摘下重放到目标顶端，对象图上线性，但产生新对象、新哈希，等于重写历史——只对自己尚未给别人的提交做；共享分支上的重写，会换掉别人脚下的地面。</p><p>合入的载体是变更评审：一段 diff、一份门禁清单、至少一双别的眼睛。<a href="/cs/vcs-changeset">版本控制与变更</a>课已经说明契约与测试要同提交；评审核对的就是这一条——diff 里有没有行为改动不带的判据。退路是 revert：生成一笔反向提交把改动抵消，历史只增不改；对已发布分支 force-push 重写历史，等于宣布所有人的克隆作废。</p>',9)),(r(),n(l,null,{default:s(()=>[i(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22%E4%B8%BB%E5%B9%B2%EF%BC%9A%E9%9A%8F%E6%97%B6%E5%8F%AF%E5%8F%91%E5%B8%83%22%5D%20--%3E%20F%5B%22%E7%9F%AD%E5%91%BD%E5%88%86%E6%94%AF%EF%BC%9A%E4%B8%80%E4%B8%AA%E5%8F%98%E6%9B%B4%22%5D%0A%20%20F%20--%3E%20RV%5B%22%E8%AF%84%E5%AE%A1%EF%BC%9Adiff%20%E4%B8%8E%E9%97%A8%E7%A6%81%22%5D%0A%20%20RV%20--%3E%20M2%5B%22%E4%B8%89%E6%96%B9%E5%90%88%E5%B9%B6%E5%9B%9E%E4%B8%BB%E5%B9%B2%22%5D%0A%20%20M2%20--%3E%20BAD%5B%22%E4%B8%8A%E7%BA%BF%E5%90%8E%E5%8F%91%E7%8E%B0%E5%9D%8F%22%5D%0A%20%20BAD%20--%3E%20REV%5B%22revert%EF%BC%9A%E5%8F%8D%E5%90%91%E6%8F%90%E4%BA%A4%22%5D%0A%20%20REV%20--%3E%20M1%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("冲突是文本三角：base、ours、theirs 各一份，机器逐行比较。它标得出「两边都动了这一行」，裁决不了意图——base 里一行 "),E("code",null,"timeout = 30"),e("，一边改成 60，一边改成 0，git 能列出冲突，说不出哪边对；语义对齐靠评审与上一课的集成层。主干健康的不变式「任何时刻可发布」还把两个决定拆开：合入不等于发布，没做完的功能用开关关着进主干。长命分支多半在隔离「没做完的功能」；开关接手这个职能之后，分支才真正短得下来。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：开关（feature flag）就是一个运行时布尔配置，把「代码已进主干」与「功能对用户可见」解耦——代码合了、开关关着，用户看不见。它接过了长命分支原来「隔离未完成功能」的职能。")],-1)),a[6]||(a[6]=E("p",null,"把文本三角逐行比较后机器能裁什么、不能裁什么，拆开看。",-1)),(r(),n(l,null,{default:s(()=>[i(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRI%5B%22base%EF%BC%9A%E5%85%B1%E5%90%8C%E7%A5%96%E5%85%88%E7%89%88%E6%9C%AC%22%5D%20--%3E%20CMP%5B%22%E9%80%90%E8%A1%8C%E6%AF%94%E8%BE%83%20ours%20%E4%B8%8E%20theirs%20%E7%9B%B8%E5%AF%B9%20base%22%5D%0A%20%20OURS%5B%22ours%EF%BC%9A%E4%B8%80%E8%BE%B9%E6%94%B9%E6%88%90%2060%22%5D%20--%3E%20CMP%0A%20%20THEIRS%5B%22theirs%EF%BC%9A%E5%8F%A6%E4%B8%80%E8%BE%B9%E6%94%B9%E6%88%90%200%22%5D%20--%3E%20CMP%0A%20%20CMP%20--%3E%20Q%7B%22%E5%90%8C%E4%B8%80%E8%A1%8C%E4%B8%A4%E8%BE%B9%E9%83%BD%E6%94%B9%E4%BA%86%E5%90%97%22%7D%0A%20%20Q%20--%20%22%E5%8F%AA%E6%9C%89%E4%B8%80%E8%BE%B9%E6%94%B9%22%20--%3E%20AUTO%5B%22%E6%9C%BA%E5%99%A8%E8%87%AA%E5%8A%A8%E5%8F%96%E9%82%A3%E8%BE%B9%E7%9A%84%E6%94%B9%E5%8A%A8%22%5D%0A%20%20Q%20--%20%22%E4%B8%A4%E8%BE%B9%E9%83%BD%E6%94%B9%22%20--%3E%20CON%5B%22%E6%A0%87%E6%88%90%E5%86%B2%E7%AA%81%EF%BC%8C%E7%95%99%E7%BB%99%E4%BA%BA%E8%A3%81%E5%86%B3%E6%84%8F%E5%9B%BE%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p><span class="marginnote">初学者容易把「合并冲突」当成 git 出故障。实际上冲突标记是机器在诚实地说「这一行我裁不了」——它能自动合的都合了，剩下的需要人比对两边意图，这正是评审存在的理由之一。</span></p><p><span class="marginnote">「天级合并」的量化理由：冲突面随分叉时长增长——分叉一周，别人对同一批文件的改动就叠了一周，base 越老，三方合并要人工裁决的行越多。把冲突从大爆炸摊薄成小摩擦，是短命分支的全部数学。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写平台按钮（托管服务的合并界面与状态机）；fork 加维护者的开源工作流只是拓扑变体；monorepo 下依赖图的合并与构建影响留到后面构建与 CI 两课；大文件与仓库容量治理不展开。开关也有成本：常年开着的开关堆积成第二套分支——入口只有一处，纪律仍在人。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单一主干加短命分支：分叉时长是唯一需要压缩的量。</li><li>三方合并以共同祖先为 base；冲突是文本三角，意图要人裁决。</li><li>变基重写历史、更换哈希，只对未共享的提交使用。</li><li>评审核对「判据与行为同进同出」；revert 用反向提交留退路，不重写历史。</li><li>开关解耦合入与发布，是分支能短命的制度前提。</li><li>出处：Chacon and Straub, <em>Pro Git</em>, 2nd ed., Apress, 2014；变更集口径见<a href="/cs/vcs-changeset">版本控制与变更</a>。</li></ul>',6))])}const D=o(p,[["render",h]]);export{F as __pageData,D as default};
